-- Product images + rich descriptions sourced from the official manufacturer
-- site discusfood.com (the client is an authorised Discusfood reseller) and
-- re-hosted in our own Supabase Storage (products/discusfood/) so the storefront
-- never depends on the external site.
--
-- For every product line we set:
--   * image_url  -> our re-hosted manufacturer photo
--   * description-> the marketing intro (shown on cards + detail page)
--   * details    -> the composition block as "Label: value" lines
--                   (Ingredients / Analytical components / Additives per kg /
--                    Feeding recommendation / Application / Storage / Product Nr.)
--                   which the product detail page renders as labelled sections.
--
-- Size variants of a line share the same photo + description; each keeps its own
-- Product Nr. Keyed by slug -> idempotent. Products with no discusfood page
-- (Anti Stress 31001, Discus Protector 32010/32030, Bio Ceramic Filter
-- 30085/30086) are intentionally left untouched.

-- 20041  super-growth  (best-heart-flake-super-growth)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/best-heart-flake-super-growth.jpg',
  description = E'Primarily designed for discus fish, this food is equally suitable for all other flake-eating ornamental fish, not least because of its high-quality ingredients.\n\nThe most outstanding feature of the composition is the beef protein. From the point of view of naturalness, discus fish do not eat cows. However, the attention here is of course to provide his protégés with a well digestible source of protein, so as not to expose them to the pressure of natural selection, but to provide the animals on the part of the feed in the best possible way.\n\nRaw beef heart, as it is processed for example in frozen food, contains collagens, which the Discus cannot break down due to a lack of enzymes. These indigestible bovine proteins can accumulate in layers on the intestinal wall, allowing parasites such as flagellates to proliferate. Fish fed raw beef heart for a long time can therefore appear weakened and emaciated, and in the further course even develop the so-called hole disease. To prevent this problem Discusfood processes in the Best Heart flake only the easily digestible beef proteins, all harmful substances have been removed. The additional enrichment with all important vitamins, minerals and dietary fiber thus results in an all-round balanced staple food for the optimal promotion of growth and health of your ornamental fish.\n\nAnother advantage of Best Heart flake compared to frozen beef heart is its "bite resistance". Neither does it disintegrate when fed, nor does it cloud the water, even though it contains only a small amount of binder and no gelatin. This contributes significantly to the relief of the aquarium filter, water changes can be reduced and no odorous protein compounds are formed. In addition, the flake offers in direct comparison a much higher nutritional value than the frozen beef heart, is not subject to a cold chain, is much easier to dose and space-saving to store.',
  details = E'Ingredients: beef proteins, rice, MSC certified krill, insect proteins, salmon oil, garlic, squid meal, yeast extracts, spirulina, kelp, prebiotics, amino acids, red pepper pigment.\nAnalytical components: Crude protein 45.8%, crude fat 8.3%, crude ash 7.2%, crude fiber 1.8%.\nAdditives per kg: Vitamins: A (3a672a) 76500 IU, C (3a300) 1730 mg, D3 (3a671) 1950 IU; with colorants; trace elements: Fe (E 1) 90 mg, Mn (3b502) 50 mg, Zn (3b603) 52 mg; with antioxidants.\nFeeding recommendation: feed 2-3 times a day as much as the fish eat within 2-5 minutes. Do not overfeed!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20041',
  updated_at = now()
WHERE slug = 'super-growth';

-- 20042  best-heart-flakes-pro-breed  (best-heart-flake-pro-breed)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/best-heart-flake-pro-breed.jpg',
  description = E'The targeted composition of high-quality vitamins, minerals and probiotics enable the ambitious discus keeper to optimally prepare his protégés for breeding and to specifically promote the spawning readiness of the selected animals. "Best Heart Flakes Pro Breed" is thus a highly functional feed, specially developed for the professional support of all discus breeders, whether professional or layman.\n\nOf course, the functionality assumes that "Best Heart Flakes Pro Breed" is not used as a main feed, but primarily for breeding purposes. Promoting spawning in groups and schools of discus fish with which breeding is not intended can lead to unnecessary territorial behavior and thus to avoidable stress within the fish community. So please follow exactly the feeding recommendation as indicated on each can.',
  details = E'Ingredients: beef proteins, rice, MSC certified krill, insect proteins, salmon oil, garlic, squid meal, yeast extracts, spirulina, kelp, prebiotics, amino acids, red pepper pigment.\nAnalytical components: Crude protein 45.8%, crude fat 8.3%, crude ash 7.2%, crude fiber 1.8%.\nAdditives per kg: Vitamins: A (3a672a) 424000 IU, C (3a300) 1180 mg, D3 (3a671) 2950 IU; with colorants; trace elements: Fe (E 1) 29 mg, Mn (3b502) 37 mg, Zn (3b603) 36 mg; with antioxidants.\nFeeding recommendation: supplementary feed, do not feed more than 40% of the daily requirement and only as much as the fish eat within 5 minutes.\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20042',
  updated_at = now()
WHERE slug = 'best-heart-flakes-pro-breed';

