-- 20060  frutti-di-mare  (frutti-di-mare)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/frutti-di-mare.jpg',
  description = E'Complete, fully extruded granules in the form of a flake, suitable for all freshwater and marine fish and lower animals. It is quickly accepted, highly digestible, very stable in shape and does not cloud the water. Balanced nutrient content and high content of vitamins and minerals ensure optimal growth and healthy development.',
  details = E'Ingredients: squid meal 11 %, krill 11 %, shrimp meal 11 %, fish meal 11 %, rice, rye, oats, peas, mussel meal 3,5 %, garlic 3 %, salmon oil, brewer''s yeast, green lipped mussel extract 1,6 %; Dry algae 4% (chlorella 1.5%, kelp 1.5%, spirulina 1%), moringa 1.5%, shiitake mushroom.\nAnalytical components: Protein 40 %, fat 8 %, crude ash 9 %, crude fiber 3 %.\nAdditives per kg: Vitamins: A (3a672a) 28000 IU, C (3a300) 210 mg, D3 (3a671) 2100 IU; with colorants; trace elements: Fe (3b103) 34 mg, Mn (3b502) 43 mg, Zn (3b603) 42 mg; with antioxidants.\nApplication: Feed several times a day. Do not overfeed!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20060',
  updated_at = now()
WHERE slug = 'frutti-di-mare';

-- 20071  beef-heart-soft-granulate  (beef-heart-soft)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/beef-heart-soft.jpg',
  description = E'In addition to our Best Heart Flakes we at Discusfood offer you with the "Beefheart Granulate" an additional possibility to do without the not undisputed frozen food and still be able to benefit from the advantages of beef proteins. From the point of view of naturalness, discus fish do not eat cows. However, the focus here is of course on providing his protégés with a protein source that is easy to utilize, so as not to subject them to the pressure of natural selection, but to provide the animals with the best possible care on the part of the feed.\n\nRaw beef heart, as it is processed for example in frozen food, contains long-chain collagens, which the discus cannot break down sufficiently due to a lack of enzymes. These indigestible bovine proteins can accumulate in layers on the intestinal wall, allowing parasites such as flagellates to proliferate. Fish fed raw beef heart for a long time can therefore appear weakened and emaciated, and in the further course even develop the so-called hole disease. To prevent this problem Discusfood processes in the "Beefheart Granulate" only the easily digestible beef proteins, all harmful substances have been removed. The additional enrichment with all important vitamins, minerals and dietary fiber results in an all-round balanced staple food for the optimal promotion of growth and health of your ornamental fish.\n\nLast but not least, the much lower water pollution caused by the granules compared to frozen food should be mentioned, because, for example, no blood is involved and the granules retain their shape in the water for a longer period of time.\n\nThe softness of the granules is a special feature, which further increases the acceptance and digestibility of the food.',
  details = E'Ingredients: fish meal, wheat gluten, fish oil, wheat, beef protein, krill meal.\nAnalytical components: Crude protein 48.8%, crude fat 13.6%, crude ash 8.3%, crude fiber 0.7%.\nAdditives per kg: Vitamins: A (3a672a) 20000 IU, D3 (3a671) 2600 IU; with colorants; trace elements: Mn (3b503) 8 mg, Zn (3b605) 70 mg; with antioxidants.\nFeeding recommendation: feed 2-3 times daily as much as the fish will eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20071',
  updated_at = now()
WHERE slug = 'beef-heart-soft-granulate';

