-- 20064  for-discus-daily-granulate  (day-by-day)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/day-by-day.jpg',
  description = E'It is not really necessary to exhaust every possibility to push the color of your discus. A solid and balanced daily diet is sufficient, which offers everything the discus needs, but without additives for e.g. ‚especially‘ fast growth and the like. "Day by Day" granules offer exactly this possibility. All important vitamins, minerals, proteins, fats and fibers are included and provide a completely sufficient nutrient supply.\n\nThe reduction of water pollution also ensures daily feeding without hesitation.\n\nAs with all our Discus Granules, we at Discusfood have of course paid special attention to the digestibility of the "Day by Day" food. As the name suggests, "Day by Day" is a complete staple food, which can be fed to cover the daily requirements or just as a supplement.',
  details = E'Ingredients: fish meal, wheat gluten, krill meal, wheat, fish oil.\nAnalytical components: Crude protein 59%, crude fat 14.5%, crude ash 12.4%, crude fiber 0.7%.\nAdditives per kg: Vitamins: A (3a672a) 20000 IU, D3 (3a671) 2000 IU; with colorants; trace elements: Mn (3b503) 12 mg, Zn (3b605) 30 mg; with antioxidants.\nFeeding recommendation: feed 2-3 times daily as much as the fish will eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20064',
  updated_at = now()
WHERE slug = 'for-discus-daily-granulate';

