-- 20083  breeder-starter-food-1  (breeder-starter-i)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/breeder-starter-i.jpg',
  description = E'for fish from 1 – 3 cm\n\nAs soon as young discus are able to pick up their food from the bottom, the "Breeder Starter Food 1" is the ideal staple food for raising. In practice, from the fifth day of free swimming, live Artemia nauplii are offered in addition to the nutrient slime of the parents. Already a few days later the young animals eat fallen nauplii also from the bottom. From this time on you can start to offer this high quality food to promote the growth optimally. From a size of approx. 3 cm the young Discus should be offered the somewhat larger "Breeder Starter Food 2" as a follow-up food. Also suitable for breeding other species!\n\nFeed your young fish 5 – 8 times daily!',
  details = E'Ingredients: fish meal, wheat gluten, krill meal, vegetable by-products, wheat, lecithin, fish oil, multivitamin complex, colorants.\nAnalytical components: Crude protein 51.2%, crude fat 6.5%, crude ash 9.6%, crude fiber 0.8%.\nAdditives per kg: Vitamins: A (3a672a) 20000 IU, D3 (3a671) 2000 IU; with colorants; trace elements: Mn (3b503) 10 mg, Zn (3b605) 24 mg; with antioxidants.\nFeeding recommendation: Feed 2-3 times daily as much as the fish eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20083',
  updated_at = now()
WHERE slug = 'breeder-starter-food-1';

-- 20084  breeder-starter-food-2  (breeder-starter-ii)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/breeder-starter-ii.jpg',
  description = E'for fish from 3 – 8 cm\n\nFollowing the raising food Breeder 1:\n\nFrom a size of approx. 3 cm, the slightly larger "Breeder Starter Food 2" should be offered to the young discus fish as a follow-up food. Also suitable for rearing other species!\n\nFeed your young fish 5-8 times a day.',
  details = E'Ingredients: fish meal, wheat gluten, glycerine, fish oil, wheat, krill meal.\nAnalytical components: Crude protein 49%, crude fat 12.2%, crude ash 10.2%, crude fiber 0.6%.\nAdditives per kg: Vitamins: A (3a672a) 20000 IU, D3 (3a671) 2600 IU; with colorants; trace elements: Mn (3b503) 12 mg, Zn (3b605) 30 mg; with antioxidants.\nFeeding recommendation: Feed 2-3 times daily as much as the fish eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20084',
  updated_at = now()
