-- 23001  pleco-catfish-algae-wafers-50g  (algae-wafers)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/algae-wafers.jpg',
  description = E'Food chips adapted to the special feeding habits of herbivorous catfishes.\n\nMost loricariids and many other fishes eat fouling. Fouling describes a comglomerate of plant and animal organisms that form a living film on rocks, boulders, wood, roots and any substrate. It is a species community of algae, bacteria, crustaceans, worms, insect larvae, and various microorganisms. This living community is food for many fish.\n\nDiscusfood has developed a new type of fish feed especially for L catfish and other bottom-dwelling fish. Its name is "Pleco & Catfish Algae Wafers". The ingredients of Pleco & Catfish Algae Wafers imitate the nutrient composition of aufwuchs. The wafers are not pressed from waste powders from other feed production. They are produced like granules, only formed into small chips. High quality granules are produced by an extruder process. This is the best way to produce high quality dry feed. This way of feed production does not need heat. All valuable nutrients and vitamins are preserved.',
  details = E'Ingredients: Crude protein 39.4%, crude fat 4.2%, crude fiber 5.3%, crude ash 9.6%.\nFeeding recommendation: Complete feed for ornamental fish. Feed this food daily in small portions.\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 23001',
  updated_at = now()
WHERE slug = 'pleco-catfish-algae-wafers-50g';

