-- 20288  beef-heart-paste-color  (beefheart-paste-color)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/beefheart-paste-color.jpg',
  description = E'In addition to the usual forms of presentation such as granules, flakes and frozen feeds, the Discusfood food pastes offer a useful alternative. Due to the individual dosage possibilities, these are suitable for small fish such as guppies, bettas and their young, as well as for large and biggest fish species such as tetras, discus, angelfish and perches. Adapted to the amount of fish and water, the shaped portions sink to the bottom and are thus accessible to all bottom dwellers such as catfish, shrimps and snails. As a small ball, the portions are excellent for sticking to the aquarium glass, making them easily accessible to open water fish. The soft consistency of the pastes is very attractive for almost all fish species. Different compositions create a balanced and varied offer for every fish keeper and breeder.',
  details = E'Ingredients: vegetable by-products, insects, protein hydrolysate from beef, vegetables (corn, spinach, moringa, garlic), cereals, krill, oils and fats (salmon oil), seeds (anise seed), algae (spirulina, chlorella), minerals, yeasts.\nAnalytical components: Crude protein 22.11%, crude fat 4.14%, crude fiber 2.22%, crude ash 6.11%.\nAdditives per kg: Vitamins: Vitamin A (3a672a) 10000 IU, Vitamin C (3a300) 80 mg, Vitamin D3 (3a671) 700 IU, Colorants: astaxanthin (2a161j) 100 mg\nFeeding recommendation: Feed 2-3 times daily as much as the fish will eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20288',
  updated_at = now()
WHERE slug = 'beef-heart-paste-color';

-- 20289  brine-shrimp-artemia-paste  (brine-shrimp-artemia-paste)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/brine-shrimp-artemia-paste.jpg',
  description = E'In addition to the usual forms of presentation such as granulate, flake and frozen feed, the Discusfood feed pastes offer a sensible alternative. Due to the individual dosage possibilities, these are suitable for small fish such as guppies, bettas and their young, as well as for large and biggest fish species such as tetras, discus, angelfish and perches. Adapted to the amount of fish and water, the shaped portions sink to the bottom and are thus accessible to all bottom dwellers such as catfish, shrimps and snails. As a small ball, the portions are excellent for sticking to the aquarium glass, making them easily accessible to open water fish. The soft consistency of the pastes is very attractive for almost all fish species. Different compositions create a balanced and varied offer for every fish keeper and breeder.',
  details = E'Ingredients: vegetable by-products, insects, Artemia cysts , vegetables (corn, spinach, moringa, garlic), cereals, krill, oils and fats (salmon oil), algae (spirulina, chlorella), minerals, yeasts.\nAnalytical components: Crude protein 23.00%, crude fat 4.25%, crude fiber 2.20%, crude ash 6.50%.\nAdditives per kg: Vitamins: Vitamin A (3a672a) 10000 IU, Vitamin C (3a300) 80 mg, Vitamin D3 (3a671) 700 IU, Colorants: astaxanthin (2a161j) 20 mg\nFeeding recommendation: Feed 2-3 times daily as much as the fish will eat within 2-5 minutes. Do not overfeed the fish!\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 20289',
  updated_at = now()
WHERE slug = 'brine-shrimp-artemia-paste';

