-- 25405  anti-tox  (anti-tox)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/anti-tox.jpg',
  description = E'Anti Tox contains high quality, highly active zeolites. These are excellent for quick removal of toxic water contamination, in case of filter system failure and very basic for fresh water treatment.\n\n– Anti Tox binds heavy metals such as copper, zinc and cadmium, as well as ammonium, chlorine and other pollutants.\n\n– acts, among other things, as a maintenance tonic, water conditioner, preventive protection, appetite stimulator, breeding promoter and water clarifier\n\n– supports the performance of the biofilter\n\n– contains no chemicals or bacteria, 100% natural\n\nAnti Tox is a suspension. During prolonged storage, the highly effective fine zeolites settle to the bottom of the bottle. For a good distribution in the bottle PLEASE SHUFFLE for 40 SECONDS! After adding to the aquarium, a slight milky cloudiness will appear. This is intentional and indicates an even distribution of the active ingredients in the water body. Overdosing is not to be expected if used properly.\n\nAdd 10 ml of Anti Tox per 100 l of fresh water at each water change. Between water changes, the optimum dosage is 5 ml for low stocking, 10 ml for normal stocking and 20 ml for high stocking per 100 l of aquarium water.\n\nFrequency of use is solely dependent on water quality.',
  details = E'Storage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 25405',
  updated_at = now()
WHERE slug = 'anti-tox';

-- 25505  royal-catappa  (catappa-royal)
UPDATE public.products SET
  image_url = 'https://vumjslsogdnexehutibj.supabase.co/storage/v1/object/public/product-images/products/discusfood/catappa-royal.jpg',
  description = E'It supports and strengthens the immune system of your fish. It can significantly improve the quality of fish water by significantly improve the quality of the fish water by reducing germs. The spawn is better protected from fungal attack. Fish suffering from fin rot and inflammations can recover more quickly. All these factors have a positive effect in the fight against fish diseases such as the spotted fever disease in salmons, the so-called goggle eye disease and pitting disease in discus fish.\n\nThe mucous membranes are particularly sustainably protected. The high-yield premium concentrate is especially suitable for when setting up a new aquarium, as well as when setting up a breeding tank, when keeping sensitive sensitive fish species, during the transport of a fish to a new\n\ntransport of a fish to a new aquarium, during a bacterial disease of the fish or during the spawning phase of discus fish and other other species. Create with a 100% natural Agent to create water that is suitable for fish.',
  details = E'Application: Add weekly & after each water change 10ml of the concentrate to 100l aquarium water. For treatment of diseases and in case of fungal infestation the dosage can be increased to 20ml or 30ml respectively. 30ml can be used.\nStorage: Not for human consumption! Store in a cool, dry place!\nProduct Nr.: 25505',
  updated_at = now()
WHERE slug = 'royal-catappa';

